// parseAmountUS inverts the en-US amount format back to cents.
func parseAmountUS(s string) int {
	s = strings.TrimSuffix(s, " ")
	neg := false
	if strings.HasPrefix(s, "(") && strings.HasSuffix(s, ")") {
		neg = true
		s = s[1 : len(s)-1]
	}
	s = strings.TrimPrefix(s, "$")
	s = strings.Replace(s, ",", "", -1)
	dot := strings.LastIndex(s, ".")
	dollars, _ := strconv.Atoi(s[:dot])
	cents, _ := strconv.Atoi(s[dot+1:])
	v := dollars*100 + cents
	if neg {
		v = -v
	}
	return v
}

func centsStr(c int) string {
	if c < 0 {
		return fmt.Sprintf("(%d)", c)
	}
	return fmt.Sprintf("%d", c)
}

